import{z as o,x as A,o as t,c as D,q as E,j as r,D as e,d as s,s as l,S as i}from"./chunks/framework.C8m1ZpeB.js";const _=JSON.parse('{"title":"NAND 闪存与 FTL","description":"","frontmatter":{"title":"NAND 闪存与 FTL","date":"2026-09-08T00:00:00.000Z","section":"cs"},"headers":[],"relativePath":"cs/nand-ftl.md","filePath":"cs/nand-ftl.md","lastUpdated":1791063341000}'),B={name:"cs/nand-ftl.md"};function d(p,a,T,N,h,c){const n=A("Mermaid");return t(),D("div",null,[a[2]||(a[2]=E('<h1 id="nand-闪存与-ftl" tabindex="-1">NAND 闪存与 FTL <a class="header-anchor" href="#nand-闪存与-ftl" aria-label="Permalink to &quot;NAND 闪存与 FTL&quot;">​</a></h1><div class="epigraph"><p>NAND 按页编程、按块擦除，不能原地改一个扇区；闪存转换层把逻辑块地址骗成「可覆盖的磁盘」，底下做重映射。</p><footer>—— 据 Harris and Harris, Digital Design and Computer Architecture；Patterson and Hennessy, Computer Organization and Design (RISC-V)；Open NAND Flash Interface 实践 整理</footer></div><p><a href="/cs/nvm-persistent">上一课</a>的字节持久仍少见。<a href="/cs/flash-memory">闪存对照</a>已区分 NOR/NAND 角色。缺口是 <strong>FTL</strong>（flash translation layer）：主机看见 512B/4KiB 逻辑块，NAND 看见页与擦除块，中间这层表如何维护。</p><h2 id="问题" tabindex="-1">问题 <a class="header-anchor" href="#问题" aria-label="Permalink to &quot;问题&quot;">​</a></h2><p>写页前若块内已有数据，通常不能覆盖：要写到新物理页，旧页标无效，逻辑地址改指新页。块满了再擦除，须先把有效页搬走。缺口不是再讲浮栅，而是这张 <strong>L2P 映射</strong>（页级、块级或混合）以及掉电时映射本身也要持久。</p><p><span class="marginnote">直觉类比：NAND 的写像圆珠笔——只能写空白页，写过的页不能涂改。要改内容只能另找一张新页重写、把旧页作废；而「作废」也不立刻清纸，要等整本（块）退役前，把还没作废的页誊抄到别处，才能整本擦掉重来。</span></p><p>ONFI/Toggle 是颗粒接口；SSD 控制器跑 FTL，主机走 NVMe/SATA——协议在 PCIe 课后。本课钉介质+FTL。</p><h3 id="ftl-不是文件系统" tabindex="-1">FTL 不是文件系统 <a class="header-anchor" href="#ftl-不是文件系统" aria-label="Permalink to &quot;FTL 不是文件系统&quot;">​</a></h3><p>文件系统也做日志与地址映射，但对象是文件与 inode。FTL 对主机呈现一块平板磁盘。两者叠床架屋（日志文件系统 + FTL）会放大写放大。把 FTL 当 ext4，内核块层职责会错。</p><p><span class="marginnote">Harris 与 Patterson/Hennessy 把闪存当存储层次底层。FTL 是 SSD 教材与厂商实践的核心。本课不抄某开源 FTL 源码结构当标准。</span></p><h2 id="方法" tabindex="-1">方法 <a class="header-anchor" href="#方法" aria-label="Permalink to &quot;方法&quot;">​</a></h2><p>读：查 L2P，向 NAND 发页读（可能多 plane）。写：分配空页、编程、更新 L2P、旧页无效。垃圾回收与磨损在下一课。映射表太大则分级，热页在 SRAM，冷页在 NAND——掉电用超级块日志恢复。</p>',12)),(t(),r(i,null,{default:e(()=>[l(n,{id:"mermaid-34",class:"mermaid",graph:"flowchart%20TD%0A%20%20LBA%5B%22%E4%B8%BB%E6%9C%BA%E9%80%BB%E8%BE%91%E5%9C%B0%E5%9D%80%22%5D%20--%3E%20FTL%5B%22L2P%20%E6%98%A0%E5%B0%84%22%5D%0A%20%20FTL%20--%3E%20PAGE%5B%22NAND%20%E7%89%A9%E7%90%86%E9%A1%B5%22%5D%0A%20%20PAGE%20--%3E%20ERASE%5B%22%E6%93%A6%E9%99%A4%E4%BB%A5%E5%9D%97%E4%B8%BA%E5%8D%95%E4%BD%8D%22%5D%0A%20%20ERASE%20--%3E%20LATER%5B%22%E5%90%8E%E8%AF%BE%EF%BC%9AGC%20%E4%B8%8E%E7%A3%A8%E6%8D%9F%E5%B9%B6%E8%A1%8C%22%5D%0A"})]),fallback:e(()=>[...a[0]||(a[0]=[s(" Loading... ",-1)])]),_:1})),a[3]||(a[3]=E('<p>ECC：NAND 原始误码率高，页内强 ECC（BCH/LDPC），与 DRAM SECDED 强度不同，仍属<a href="/cs/soft-error-ecc">软错误</a>家族的介质版。</p><h2 id="机制" tabindex="-1">机制 <a class="header-anchor" href="#机制" aria-label="Permalink to &quot;机制&quot;">​</a></h2><p>SSD 内部并行（多 die、plane）让 FTL 把用户写打到不同通道，类似 DRAM 通道但擦除约束不同。持久内存的字节语义在此不提供。磁盘几何课会对照：HDD 可原地覆盖扇区，无 FTL。</p><p><span class="marginnote">数字实例：一个 256 KB 的擦除块通常含 64 个 4 KB 页。主机只想改 4 KB，FTL 也要找新空页写入、旧页作废。垃圾回收的划算程度看有效页数量：64 页里只剩 1 页有效时，搬 1 页就能擦掉整块；若 60 页都有效，就要搬 60 页——这就是写放大的直接来源。</span></p><p><span class="marginnote">常见误区：初学者以为「在 SSD 上覆盖保存文件」就是原地改写。实际上主机发来的每一次覆盖写都被 FTL 改道到新的物理页，旧页只是被标成无效；真正能原地覆盖扇区的是 HDD，那正是它不需要 FTL 的原因。</span></p>',5)),(t(),r(i,null,{default:e(()=>[l(n,{id:"mermaid-50",class:"mermaid",graph:"flowchart%20TD%0A%20%20W%5B%22%E4%B8%BB%E6%9C%BA%E6%94%B9%E5%86%99%E9%80%BB%E8%BE%91%E5%9D%97%20L5%22%5D%20--%3E%20NEW%5B%22%E5%86%99%E5%88%B0%E6%96%B0%E7%89%A9%E7%90%86%E9%A1%B5%20P2b%22%5D%0A%20%20NEW%20--%3E%20UPD%5B%22L2P%EF%BC%9AL5%20%E6%94%B9%E6%8C%87%20P2b%22%5D%0A%20%20UPD%20--%3E%20OLD%5B%22%E6%97%A7%E9%A1%B5%20P2a%20%E6%A0%87%E8%AE%B0%E6%97%A0%E6%95%88%22%5D%0A%20%20OLD%20--%3E%20MIX%5B%22%E5%9D%97%E5%86%85%E6%9C%89%E6%95%88%E9%A1%B5%E4%B8%8E%E6%97%A0%E6%95%88%E9%A1%B5%E6%B7%B7%E4%BD%8F%22%5D%0A%20%20MIX%20--%3E%20GC%5B%22%E6%93%A6%E9%99%A4%E5%89%8D%E5%85%88%E6%90%AC%E8%B5%B0%E6%9C%89%E6%95%88%E9%A1%B5%22%5D%0A%20%20GC%20--%3E%20E%5B%22%E6%95%B4%E5%9D%97%E6%93%A6%E9%99%A4%E5%90%8E%E5%8F%AF%E5%A4%8D%E7%94%A8%22%5D%0A"})]),fallback:e(()=>[...a[1]||(a[1]=[s(" Loading... ",-1)])]),_:1})),a[4]||(a[4]=E('<h2 id="边界" tabindex="-1">边界 <a class="header-anchor" href="#边界" aria-label="Permalink to &quot;边界&quot;">​</a></h2><p>本课不讲 3D NAND 字线工艺，不把 TLC/QLC 电压阈值当光刻课。不写加密盘的密钥槽细节（可点名存在）。</p><p>后课默认：NAND 不能原地覆盖；FTL 把 LBA 映到物理页并留下无效页给 GC。</p><h2 id="小结" tabindex="-1">小结 <a class="header-anchor" href="#小结" aria-label="Permalink to &quot;小结&quot;">​</a></h2><ul><li>NAND：页写块擦；FTL 提供可覆盖的逻辑磁盘。</li><li>L2P 自身要可恢复；与文件系统叠层会写放大。</li><li>下一课并行、回收与磨损。</li><li>出处：Harris and Harris；Patterson and Hennessy, COD；ONFI 实践。</li></ul>',5))])}const f=o(B,[["render",d]]);export{_ as __pageData,f as default};
